use reqwest::blocking::Client;use serde::Serialize;use std::{env,fs,path::Path,time::Duration};
pub const DEFAULT_URL:&str="https://www.isrgrajan.com/gecko/tts/index.php";
#[derive(Debug)]pub struct GeckoTTSError{pub status:u16,pub message:String}impl std::fmt::Display for GeckoTTSError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"Gecko TTS HTTP {}: {}",self.status,self.message)}}impl std::error::Error for GeckoTTSError{}
#[derive(Serialize)]struct Payload<'a>{#[serde(skip_serializing_if="Option::is_none")]text:Option<&'a str>,#[serde(skip_serializing_if="Option::is_none")]ssml:Option<&'a str>,#[serde(skip_serializing_if="Option::is_none")]lang:Option<&'a str>,format:&'a str,stream:bool}
pub struct GeckoTTS{key:String,secret:String,url:String,http:Client}
impl GeckoTTS{pub fn new(key:Option<String>,secret:Option<String>)->Result<Self,Box<dyn std::error::Error>>{let key=key.or_else(||env::var("GECKO_TTS_KEY").ok()).unwrap_or_default();let secret=secret.or_else(||env::var("GECKO_TTS_SECRET").ok()).unwrap_or_default();if key.is_empty()||secret.is_empty(){return Err("Set GECKO_TTS_KEY and GECKO_TTS_SECRET".into())}Ok(Self{key,secret,url:env::var("GECKO_TTS_URL").unwrap_or_else(|_|DEFAULT_URL.into()),http:Client::builder().timeout(Duration::from_secs(90)).build()?})}
pub fn synthesize(&self,text:Option<&str>,ssml:Option<&str>,lang:Option<&str>,format:&str)->Result<Vec<u8>,Box<dyn std::error::Error>>{let t=text.map(|x|!x.is_empty()).unwrap_or(false);let s=ssml.map(|x|!x.is_empty()).unwrap_or(false);if t==s{return Err("Provide exactly one non-empty text or ssml".into())}let p=Payload{text:if t{text}else{None},ssml:if s{ssml}else{None},lang,format,stream:true};let r=self.http.post(&self.url).header("X-API-Key",format!("{}:{}",self.key,self.secret)).json(&p).send()?;let status=r.status();let body=r.bytes()?.to_vec();if !status.is_success(){return Err(Box::new(GeckoTTSError{status:status.as_u16(),message:String::from_utf8_lossy(&body).chars().take(1200).collect()}))}Ok(body)}
pub fn synthesize_to_file(&self,path:impl AsRef<Path>,text:&str,lang:Option<&str>,format:&str)->Result<(),Box<dyn std::error::Error>>{fs::write(path,self.synthesize(Some(text),None,lang,format)?)?;Ok(())}}
